const data = $input.all()[0].json;
const opps = data.opportunities || [];
const lastId = opps.length > 0 ? opps[opps.length - 1].id : null;
return [{ json: { page1: opps, lastId, hasMore: opps.length === 100 } }];

const STAGE_MAP = {
  '7c81c61e-842c-468c-b04e-323ee3c5d250': 'New Inquiry',
  'e393711e-4729-4cc4-b7a1-ecc710129858': 'HP Applications',
  '366879a9-3eaf-4700-93d9-f6f775457e09': 'For Follow Up',
  '6a9fe7a6-26a1-4acd-a92b-f95b67e83dfa': 'Info Incomplete',
  'a3edb190-8da2-4af7-ac5c-c4b7c605b6c8': 'Out of Service Area – Waitlist',
  '930fab05-e7ca-486d-a5b0-8af0ab210db2': 'For HP Matching',
  'b23c75fa-e52e-473a-862f-c700f8cf3089': 'Worker options sent',
  '94beffdb-a4a5-45d8-97cb-4ff65f30aec8': 'Worker assigned',
  '8c10fca2-c8d4-421a-8f51-9f8bf3708d99': 'Assessment/Quotation (Cleaning)',
  'b997bdc5-88de-42ed-a426-bc5ff60a14fd': 'Assessment/Quotation (Skilled)',
  '5419fa36-ee9c-4a4e-82a2-a65155e9d833': 'For HP Matching',
  'dc963318-adbf-4765-8970-3628a000641d': 'No HP Match',
  'e22b9210-9db3-4023-9a68-9e9221a4e0ba': 'FaceCard / For Downpayment',
  'fd82ade4-cb50-46ac-9f33-83e999379a89': 'Downpayment verification',
  'f43ca21f-0394-410e-9271-b988e4275a51': 'Confirmed',
  '774be07c-a608-44ff-964e-b6eeb1d11cfb': "Today's Booking",
  '2b1848d6-8df9-4440-ba20-b6b1509e736c': 'Job In Progress',
  '4a31c624-f5a4-41a8-8fe5-3c60c20b0291': 'Full Payment Confirmation',
  '3417461b-910b-44e1-96ee-cb84fa203f6a': 'HP Payment',
  'f6d6c3a3-a410-4ee4-b235-9e882dd2da5a': 'Job Completed',
  '8385f79f-70bc-48a9-8299-51f8ca3f3b2a': 'E-Receipt Sent',
  'b5020622-a1cd-463e-b844-54fd6fb1acb7': 'Cancelled by Client',
  '4bab4d11-6fb3-4167-b89c-c9f3c0839633': 'Cancelled by HP',
  '3b459ba0-2464-46c0-9383-a54d80903dea': 'Complaint_Rework',
  'e2b91d1d-1ab4-448a-ae6f-f258e69eac04': 'For Reschedule',
  'c34897e0-1887-4e6f-b6ad-35ef68382c95': 'Dump',
  'b54f6ad9-9b21-4f25-925b-250ab252604e': 'NCNS'
};
const CH_MAP = {
  TYPE_FACEBOOK:'Messenger',TYPE_SMS:'SMS',TYPE_PHONE:'SMS',
  TYPE_INSTAGRAM:'Instagram',TYPE_WHATSAPP:'Messenger',
  TYPE_LIVE_CHAT:'SMS',TYPE_WEBCHAT:'SMS',TYPE_VIBER:'Viber'
};
function parseName(raw) {
  if (!raw) return { code:'', service:'General Service' };
  const parts = raw.split(' - ');
  const code = parts[0]?.trim() || '';
  const service = parts.length >= 3 ? parts[parts.length-1].trim() : (parts[1]?.trim() || raw);
  return { code, service: service || 'Service' };
}

const page1 = $('Extract Cursor').all()[0]?.json?.page1 || [];
const page2 = $('Fetch Page 2').all()[0]?.json?.opportunities || [];
const confirmedOpps = $('Fetch Confirmed').all()[0]?.json?.opportunities || [];
const scheduledOpps = $('Fetch Scheduled').all()[0]?.json?.opportunities || [];
const completedOpps = $('Fetch Completed').all()[0]?.json?.opportunities || [];

const generalOpps = [...page1, ...page2];
const counts = {};
const bookings = [];
let paymentTotal = 0, monthInquiries = 0, todayInquiries = 0;

const PAYMENT_STAGES = ['FaceCard / For Downpayment','Downpayment verification','Full Payment Confirmation'];
const MONTH_START = new Date(); MONTH_START.setDate(1); MONTH_START.setHours(0,0,0,0);
const wd = new Date().getDay();
const WEEK_START = new Date(); WEEK_START.setDate(WEEK_START.getDate()-(wd===0?6:wd-1)); WEEK_START.setHours(0,0,0,0);
const TODAY_START = new Date(); TODAY_START.setHours(0,0,0,0);

generalOpps.forEach(o => {
  const stage = STAGE_MAP[o.pipelineStageId] || 'Unknown';
  counts[stage] = (counts[stage] || 0) + 1;
  if (PAYMENT_STAGES.includes(stage)) paymentTotal += (o.monetaryValue || 0);
  const created = o.createdAt ? new Date(o.createdAt) : null;
  if (stage === 'New Inquiry' && created && created >= TODAY_START) todayInquiries++;
  if (created && created >= MONTH_START) monthInquiries++;
  if (bookings.length < 30) {
    const { code, service } = parseName(o.name);
    bookings.push({
      id: code || ('HS-'+o.id.slice(-4).toUpperCase()), ghlId: o.id,
      client: o.contact?.name || o.name || 'Client', service,
      city: o.contact?.city || '', stage,
      when: created ? created.toLocaleDateString('en-PH',{month:'short',day:'numeric'}) : '',
      amount: o.monetaryValue||0, channel: CH_MAP[o.contact?.type]||'SMS', hp:null, note:''
    });
  }
});

const todayScheduled = scheduledOpps.length;
const weekConfirmed = confirmedOpps.filter(o => o.updatedAt && new Date(o.updatedAt) >= WEEK_START).length;
const completedThisMonth = completedOpps.filter(o => o.updatedAt && new Date(o.updatedAt) >= MONTH_START).length;
const conversionRate = monthInquiries > 0 ? ((completedThisMonth/monthInquiries)*100).toFixed(1) : '0.0';

counts['Confirmed'] = (counts['Confirmed'] || 0) + confirmedOpps.length;
counts["Today's Booking"] = todayScheduled;
counts['Job Completed'] = (counts['Job Completed'] || 0) + completedOpps.length;

return [{ json: { counts, bookings, paymentTotal, completedThisMonth, total: generalOpps.length, todayInquiries, weekConfirmed, todayScheduled, monthInquiries, conversionRate, updatedAt: new Date().toISOString() } }];
